const e = $input.first().json;
const workflow = e.workflow?.name || e.workflowName || 'Unbekannt';
const executionId = e.execution?.id || e.executionId || '–';
const ts = e.execution?.startedAt || new Date().toISOString();
const errMsg = (e.execution?.error?.message || e.error?.message || JSON.stringify(e)).slice(0, 1200);
const node = e.execution?.lastNodeExecuted || e.lastNodeExecuted || '–';
const text = `🚨 n8n Fehler\n\nWorkflow: ${workflow}\nExecution: ${executionId}\nZeit: ${ts}\nNode: ${node}\n\nFehler:\n${errMsg}`;
const brain = `[n8n Fehler] Workflow ${workflow}, Execution ${executionId}, Node ${node}. ${errMsg.slice(0, 400)}. Nils: prüfen und fixen.`;
return [{ json: { text, brain_message: brain, workflow, executionId, timestamp: ts, errorMessage: errMsg, node } }];
